async function download(blob,name){const cap=window.Capacitor;if(cap&&cap.isNativePlatform&&cap.isNativePlatform()&&cap.Plugins&&cap.Plugins.Filesystem){try{const fs=cap.Plugins.Filesystem;if(fs.requestPermissions){try{await fs.requestPermissions()}catch(e){}}const data=await new Promise((res,rej)=>{const r=new FileReader();r.onload=()=>res(String(r.result).split(',')[1]);r.onerror=rej;r.readAsDataURL(blob)});const saved=await fs.writeFile({path:name,data,directory:'DOCUMENTS'});tell('已保存到本机文档：'+name);if(cap.Plugins.Share){cap.Plugins.Share.share({title:name,url:saved.uri}).catch(()=>{})}return}catch(err){console.warn('native save failed',err)}}const a=document.createElement('a'),url=URL.createObjectURL(blob);a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),10000)}
function saveProject(){const blob=new Blob([JSON.stringify({...state,app:'afterimage-studio'},null,2)],{type:'application/json'});download(blob,'余像-'+state.title.replace(/\.[^.]+$/,'')+'.json');savedState=JSON.stringify(state);tell('工程已下载，包含原图、图层和效果参数')}

async function loadProject(file){if(!file)return;try{if(file.size>70*1024*1024)throw new Error('工程文件过大');const v=validateProject(JSON.parse(await file.text()));await Promise.all(v.layers.filter(l=>l.type==='image').map(l=>imageLoad(l.src)));checkpoint();state=v;savedState=JSON.stringify(state);time=0;playing=false;cropMode=false;hydrate();renderLibrary();tell('工程恢复完成')}catch(e){tell('打开失败：'+e.message)}finally{$('projectFile').value=''}}
// —— 导出用渲染线程：把逐帧渲染移出主线程，失败时自动回退主线程 ——
let renderWorker=null,renderWorkerBroken=false,renderSeq=0;const renderPending=new Map(),workerAssets=new Map();
function getRenderWorker(){
 if(renderWorker||renderWorkerBroken)return renderWorker;
 if(typeof Worker!=='function'||typeof createImageBitmap!=='function'){renderWorkerBroken=true;return null}
 try{
  renderWorker=new Worker('./render-worker.js',{type:'module'});
  renderWorker.onmessage=e=>{const d=e.data||{},job=renderPending.get(d.id);if(!job)return;renderPending.delete(d.id);if(d.type==='frame')job.resolve({image:d.bitmap,width:d.width,height:d.height});else if(d.type==='error')job.reject(new Error(d.message||'渲染线程出错'))};
  renderWorker.onerror=e=>{renderWorkerBroken=true;console.warn('渲染线程不可用，已回退主线程渲染',e.message||'');for(const job of renderPending.values())job.reject(new Error('渲染线程不可用'));renderPending.clear()};
 }catch{renderWorkerBroken=true;renderWorker=null}
 return renderWorker;
}
async function workerDocument(){
 const w=getRenderWorker();if(!w)return null;
 const entries=[];
 for(const l of state.layers){
  if(l.type!=='image'||!l.src||workerAssets.has(l.src))continue;
  const im=assets.get(l.src);if(!im)return null;
  try{const bmp=await createImageBitmap(im);workerAssets.set(l.src,'asset'+(workerAssets.size+1));entries.push([workerAssets.get(l.src),bmp])}catch{return null}
 }
 if(entries.length)w.postMessage({type:'assets',entries},entries.map(e=>e[1]));
 return {...state,layers:state.layers.map(l=>l.type==='image'&&l.src&&workerAssets.has(l.src)?{...l,src:workerAssets.get(l.src)}:l)};
}
async function renderFrame(maxSide,t){
 const worker=getRenderWorker();
 if(worker){
  const doc=await workerDocument();
  if(doc){
   const id=++renderSeq;
   try{
    const pending=new Promise((resolve,reject)=>{renderPending.set(id,{resolve,reject});worker.postMessage({type:'render',id,doc,maxSide,time:t})});
    return await pending;
   }catch{renderPending.delete(id)}
  }
 }
 return render(state,assets,maxSide,t);
}
function frameSource(frame){return frame&&frame.image?frame.image:frame}
function releaseFrame(frame){frame&&frame.image&&frame.image.close&&frame.image.close()}
function frameCanvas(frame){if(!frame||!frame.image)return frame;const c=newCanvas(frame.width,frame.height);c.getContext('2d').drawImage(frame.image,0,0);releaseFrame(frame);return c}
async function exportImage(){if(exporting)return;exporting=true;exportCancel=false;const format=$('exportFormat').value,side=$('exportSize').value==='original'?4096:Number($('exportSize').value),quality=Number($('exportQuality').value)||.86,progress=$('exportProgress'),cancel=$('exportCancel');$('doExport').disabled=true;playing=false;playStart=0;progress.hidden=false;progress.value=0;cancel.hidden=false;$('exportStatus').textContent='正在渲染…';await new Promise(r=>setTimeout(r,40));try{if(format==='video'){await exportVideo(Math.min(side,1200),quality);return}if(format==='gif'){await exportGif(Math.min(side,480));return}const result=frameCanvas(await renderFrame(side,time));if(exportCancel)throw new Error('__cancelled');progress.value=60;let out=result;if(format==='jpeg'&&state.transparent){out=newCanvas(result.width,result.height);const x=out.getContext('2d');x.fillStyle=state.background;x.fillRect(0,0,out.width,out.height);x.drawImage(result,0,0)}const mime='image/'+format,blob=await new Promise(r=>out.toBlob(r,mime,quality));if(!blob)throw new Error('编码失败');if(blob.type!==mime)throw new Error('浏览器不支持此格式，请改用 PNG');progress.value=100;download(blob,'余像-'+Date.now()+'.'+(format==='jpeg'?'jpg':format));$('exportStatus').textContent=`已导出 ${out.width} × ${out.height}，${(blob.size/1024/1024).toFixed(2)} MB`;tell('作品已导出')}catch(e){$('exportStatus').textContent=e.message==='__cancelled'?'已取消导出':'导出失败：'+e.message}finally{exporting=false;exportCancel=false;$('doExport').disabled=false;progress.hidden=true;cancel.hidden=true;dirty=true}}
async function exportVideo(side,quality=.86){const fps=30,total=Math.max(1,Math.round(state.duration*fps)),sc=Math.min(1,side/Math.max(state.width,state.height)),out=newCanvas(Math.round(state.width*sc),Math.round(state.height*sc)),x=out.getContext('2d');if(typeof VideoEncoder==='function'&&typeof VideoFrame==='function'){try{return await exportVideoOffline(out,x,fps,total,quality)}catch(e){if(e.message==='__cancelled')throw e;console.warn('离线视频编码不可用，回退实时录制',e.message)}}return exportVideoLegacy(out,x,fps,total,quality)}
// WebCodecs 离线编码：逐帧编码成 VP9 / VP8，再由本地封装器写 WebM，不依赖页面在前台，也不受实时采样抖动影响。
async function exportVideoOffline(out,x,fps,total,quality){
 const maxSide=Math.max(out.width,out.height),candidates=[['vp09.00.10.08','V_VP9'],['vp8','V_VP8']];let picked=null;
 for(const [codec,codecId] of candidates){const config={codec,width:out.width,height:out.height,framerate:fps,bitrate:Math.round(6400000*quality/.86),latencyMode:'quality'};try{const support=await VideoEncoder.isConfigSupported(config);if(support?.supported){picked={config,codecId};break}}catch{}}
 if(!picked)throw new Error('浏览器没有可用的 WebCodecs 视频编码器');
 const chunks=[];let failure=null;
 const encoder=new VideoEncoder({output:chunk=>{const data=new Uint8Array(chunk.byteLength);chunk.copyTo(data);chunks.push({data,timestamp:chunk.timestamp,key:chunk.type==='key'})},error:e=>{failure=e}});
 encoder.configure(picked.config);
 try{
  for(let i=0;i<total;i++){
   if(exportCancel)throw new Error('__cancelled');
   if(failure)throw failure;
   const frame=await renderFrame(maxSide,Math.min(state.duration-1e-6,i/fps));
   x.clearRect(0,0,out.width,out.height);
   if(state.transparent){x.fillStyle=state.background;x.fillRect(0,0,out.width,out.height)}
   x.drawImage(frameSource(frame),0,0);releaseFrame(frame);
   const vf=new VideoFrame(out,{timestamp:Math.round(i*1000000/fps),duration:Math.round(1000000/fps)});
   encoder.encode(vf,{keyFrame:i%(fps*2)===0});vf.close();
   while(encoder.encodeQueueSize>8&&!failure){await new Promise(r=>setTimeout(r,4));if(exportCancel)throw new Error('__cancelled')}
   const pct=Math.min(90,Math.round((i+1)/total*90));
   $('exportProgress').value=pct;$('exportStatus').textContent=`正在离线编码 ${pct}% · ${fps} fps · 无需保持前台`;
   if(i%6===0)await new Promise(r=>setTimeout(r));
  }
  $('exportStatus').textContent='正在封装 WebM…';
  try{await encoder.flush()}catch(e){failure=failure||e}
  if(failure)throw failure;
  if(exportCancel)throw new Error('__cancelled');
 }finally{try{if(encoder.state!=='closed')encoder.close()}catch{}}
 if(!chunks.length)throw new Error('编码结果为空');
 const bytes=buildWebm({width:out.width,height:out.height,fps,codec:picked.codecId,chunks});
 const blob=new Blob([bytes],{type:'video/webm'});
 download(blob,'余像-动态-'+Date.now()+'.webm');
 $('exportProgress').value=100;
 $('exportStatus').textContent=`已导出 ${state.duration} 秒 WebM · ${fps} fps · ${out.width}×${out.height} · ${(blob.size/1024/1024).toFixed(2)} MB`;
 tell('动态视频已导出')
}
async function exportVideoLegacy(out,x,fps,total,quality=.86){if(!window.MediaRecorder||!HTMLCanvasElement.prototype.captureStream)throw new Error('此浏览器不支持视频导出，请使用 Chrome 或 Edge');const mime=['video/webm;codecs=vp9','video/webm;codecs=vp8','video/webm'].find(x=>MediaRecorder.isTypeSupported(x));if(!mime)throw new Error('此浏览器没有可用的 WebM 编码器');let stream=out.captureStream(0),track=stream.getVideoTracks()[0];const manual=!!(track&&track.requestFrame);if(!manual){stream.getTracks().forEach(t=>t.stop());stream=out.captureStream(fps)}const chunks=[],rec=new MediaRecorder(stream,{mimeType:mime,videoBitsPerSecond:Math.round(6400000*quality/.86)});const finished=new Promise((resolve,reject)=>{rec.ondataavailable=e=>{if(e.data.size)chunks.push(e.data)};rec.onstop=resolve;rec.onerror=e=>reject(e.error||new Error('录制失败'))});rec.start(250);const start=performance.now();try{for(let i=0;i<total;i++){if(exportCancel)throw new Error('__cancelled');if(document.hidden)throw new Error('页面进入后台，录制已取消，请保持前台重试');const frame=await renderFrame(Math.max(out.width,out.height),Math.min(state.duration-1e-6,i/fps));const wait=start+i*(1000/fps)-performance.now();if(wait>0)await new Promise(r=>setTimeout(r,wait));x.clearRect(0,0,out.width,out.height);if(state.transparent){x.fillStyle=state.background;x.fillRect(0,0,out.width,out.height)}x.drawImage(frameSource(frame),0,0);releaseFrame(frame);if(manual)track.requestFrame();const pct=Math.min(99,Math.round((i+1)/total*100));$('exportProgress').value=pct;$('exportStatus').textContent=`正在录制 ${pct}% · ${fps} fps · 保持页面前台`}await new Promise(r=>setTimeout(r,300));rec.stop();await finished;if(exportCancel)throw new Error('__cancelled');const blob=new Blob(chunks,{type:'video/webm'});if(!blob.size)throw new Error('录制结果为空，请重试或改用 GIF');download(blob,'余像-动态-'+Date.now()+'.webm');$('exportStatus').textContent=`已导出 ${state.duration} 秒 WebM · ${fps} fps · ${(blob.size/1024/1024).toFixed(2)} MB`;tell('动态视频已导出')}finally{if(rec.state!=='inactive')rec.stop();stream.getTracks().forEach(t=>t.stop())}}
async function exportGif(side){const mode=$('gifDither')?.value||'fs',dither=mode==='off'?false:mode==='bayer'?true:'fs',fps=Math.max(4,Math.min(15,Math.floor(120/state.duration))),total=Math.max(1,Math.round(state.duration*fps)),delay=Math.round(100/fps);const sc=Math.min(1,side/Math.max(state.width,state.height)),out=newCanvas(Math.round(state.width*sc),Math.round(state.height*sc)),x=out.getContext('2d',{willReadFrequently:true}),frames=[];for(let i=0;i<total;i++){if(exportCancel)throw new Error('__cancelled');x.clearRect(0,0,out.width,out.height);if(state.transparent){x.fillStyle=state.background;x.fillRect(0,0,out.width,out.height)}const frame=await renderFrame(side,Math.min(state.duration-1e-6,i/fps));x.drawImage(frameSource(frame),0,0);releaseFrame(frame);frames.push(quantizeFrame(x.getImageData(0,0,out.width,out.height).data,out.width,dither));$('exportProgress').value=Math.min(90,Math.round((i+1)/total*90));$('exportStatus').textContent=`正在渲染 GIF ${i+1}/${total} 帧`;if(i%4===0)await new Promise(r=>setTimeout(r))}$('exportStatus').textContent='正在编码 GIF…';await new Promise(r=>setTimeout(r,30));const bytes=encodeGif({width:out.width,height:out.height,frames,delay});if(exportCancel)throw new Error('__cancelled');const blob=new Blob([bytes],{type:'image/gif'});download(blob,'余像-动图-'+Date.now()+'.gif');$('exportProgress').value=100;$('exportStatus').textContent=`已导出 GIF ${out.width}×${out.height} · ${total} 帧 · ${fps} fps · ${(blob.size/1024/1024).toFixed(2)} MB`;tell('GIF 动图已导出')}
$('importBase').onclick=()=>{importMode='base';$('imageFile').click()};$('addImage').onclick=()=>{importMode='layer';$('imageFile').click()};$('imageFile').onchange=e=>importImage(e.target.files[0]);$('openProject').onclick=()=>$('projectFile').click();$('projectFile').onchange=e=>loadProject(e.target.files[0]);$('saveProject').onclick=saveProject;$('undo').onclick=()=>undoAction();$('redo').onclick=()=>undoAction(true);$('compare').onclick=()=>{compare=!compare;$('compare').setAttribute('aria-pressed',compare);dirty=true};$('reset').onclick=()=>{const target=effectTarget();if(!target)return;checkpoint();state.effects=state.effects.filter(e=>e.target!==target);state.recipe='原始画面';renderStack();change();scheduleLibraryRefresh()};$('newText').onclick=()=>addElement('text');$('addEffectHint').onclick=()=>{tab='effects';category='全部';updateTab()};$('play').onclick=()=>{playing=!playing;playStart=0};$('time').oninput=()=>{playing=false;playStart=0;time=Number($('time').value)/1000*state.duration;dirty=true};$('duration').onchange=()=>{checkpoint();const next=Number($('duration').value);for(const l of state.layers)if(l.timing){l.timing.start=Math.min(l.timing.start,next-.05);l.timing.end=Math.max(l.timing.start+.05,Math.min(l.timing.end,next))}state.duration=next;time=0;playStart=0;change()};$('bgColor').onchange=()=>{checkpoint();state.background=$('bgColor').value;change()};$('transparent').onchange=()=>{checkpoint();state.transparent=$('transparent').checked;change()};$('ratio').onchange=()=>{if($('ratio').value==='original')return;checkpoint();const ratio=Number($('ratio').value),ow=state.width,oh=state.height;if(ow/oh>ratio)state.width=Math.round(oh*ratio);else state.height=Math.round(ow/ratio);const dx=(state.width-ow)/2,dy=(state.height-oh)/2;state.layers.forEach(l=>{l.x+=dx;l.y+=dy});$('ratio').value='original';hydrate();tell('已居中裁切画幅；原图保留，可拖动调整构图')};
function updateTab(){document.body.dataset.library=tab;document.querySelectorAll('[data-tab]').forEach(b=>b.classList.toggle('active',b.dataset.tab===tab));libraryCategories();renderLibrary()}document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{tab=b.dataset.tab;category='全部';$('search').value='';updateTab()});$('search').oninput=renderLibrary;$('saveRecipe').onclick=()=>{if(!state.effects.length){tell('先添加几个效果再收藏');return}const name=prompt('给这个配方取个名字',state.recipe==='自定义配方'?'我的配方':state.recipe);if(!name?.trim())return;const currentTarget=effectTarget();const scopedEffects=state.effects.filter(e=>e.target===currentTarget);if(!scopedEffects.length){tell('当前作用范围没有效果可收藏');return}const p={name:name.trim().slice(0,40),en:'MY RECIPE',cat:'收藏',chain:scopedEffects.map(e=>({type:e.type,params:{...e.params},color:e.color,color2:e.color2,enabled:e.enabled,target:'all'}))};favorites.push(p);try{localStorage.setItem('afterimage-recipes',JSON.stringify(favorites));tell('配方已收藏在此浏览器，作用范围保存为整幅作品')}catch{tell('浏览器空间不足，请保存工程文件')}if(category==='收藏')renderLibrary()};
$('exportOpen').onclick=()=>$('exportDialog').showModal();$('doExport').onclick=exportImage;$('exportCancel').onclick=()=>{exportCancel=true;$('exportStatus').textContent='正在取消导出…'};
function showInfo(html){$('infoContent').innerHTML=html;$('infoDialog').showModal()}
$('aboutOpen').onclick=()=>showInfo(`<span class="eyebrow">A SMALL GUIDE</span><h2>让图像多一种可能。</h2><p>① 导入照片，或使用内置摄影示例。② 选一个配方。③ 在右侧展开效果，调整参数、作用范围与顺序。④ 添加文字和贴片，再导出作品。</p><h3>图层效果、蒙版与运动</h3><p>新效果和配方默认作用于选中图层，套用配方只替换这个图层的效果。在效果面板可改为整幅作品。边框四角等比缩放，圆形箭头旋转，按 Shift 旋转吸附 15°；画布拖动移动图层。方向键微调，Shift 加速，Ctrl/Cmd+D 复制，Delete 删除。</p><p>图层面板含文字自动换行、段落对齐、行距，以及矩形/椭圆蒙版、反相和羽化。运动按全局时长往返循环，可设置位移、旋转与终点大小。编辑边框回到动画起点。曲线为五点分段线性映射，支持总 RGB 或单通道。</p><h3>图层与构图</h3><p>点击图层后可在画布拖动。尺寸、旋转、透明度、混合模式与投影都在右侧。裁切保留源图，拖动照片可重新构图。文字字号决定实际字形大小，宽高用于拖选范围；环形文字的宽度控制圆环直径。</p><h3>动态与导出</h3><p>播放键预览颗粒、扫描、色相、故障和动态文字。部分效果不是无缝循环。静态导出最高长边 4096，视频导出为无声 WebM、最高长边 1200；支持 WebCodecs 的设备逐帧离线编码，无需保持前台，不支持的浏览器回退到实时录制。GIF 输入目前只读首帧。</p><h3>展厅与取色</h3><p>风格展厅将当前图层生成 ${PRESETS.length} 种效果预览；选择卡片进入大图试映，支持原图对照、收藏，再应用配方。下载联系表会生成当前筛选下的对照图。取色按钮启动一次画布采样；色卡提取统计当前作品的近似主色，点色块选择，再用“用于图层”给选中的文字或形状上色。原图对比开启后，可拖动下方滑块移动分割线。</p><h3>保存</h3><p>编辑会自动保存在本机浏览器，重新载入后继续上次的作品。保存工程仍会下载含图片和参数的 JSON，建议重要作品另存备份。收藏配方仅保存在当前浏览器。Ctrl/Cmd+Z 撤销，Ctrl/Cmd+Shift+Z 重做；空格播放/暂停。</p><p>照片不上传服务器。云端私有站点只存放应用代码；浏览器可能请求字体文件。</p>`);
$('sourcesOpen').onclick=()=>showInfo(`<span class="eyebrow">BUILT WITH INTENTION</span><h2>效果与来源</h2><p>本版包含 ${Object.keys(EFFECTS).length} 个参数化效果、${PRESETS.length} 套配方。图像处理与图层引擎为本项目编写，没有打包调研中的商业贴图或第三方预设。内置照片来自 Unsplash，仅作为创作示例。</p><h3>界面设计参考</h3><p><a target="_blank" rel="noopener" href="https://www.awwwards.com/sites/cosmos">Cosmos</a> · <a target="_blank" rel="noopener" href="https://www.awwwards.com/sites/readymag-design-workout">Readymag Design Workout</a> · <a target="_blank" rel="noopener" href="https://www.awwwards.com/sites/playtype">Playtype</a>。参考图像主导的舞台、创作工具的直接操作与字体尺度；界面代码为原创实现。</p><p><a target="_blank" rel="noopener" href="https://images.unsplash.com/photo-1500530855697-b586d89ba3ee">示例照片来源</a> · <a target="_blank" rel="noopener" href="https://unsplash.com/license">Unsplash 许可</a></p><h3>本轮参考</h3><p><a href="https://www.awwwards.com/sites/unseen-studio" target="_blank" rel="noopener">Unseen Studio</a> · <a href="https://www.awwwards.com/sites/lusion-labs" target="_blank" rel="noopener">Lusion Labs</a> · <a href="https://github.com/evanw/glfx.js" target="_blank" rel="noopener">glfx.js</a> · <a href="https://github.com/satyarth/pixelsort" target="_blank" rel="noopener">pixelsort</a>。用于交互与算法方向研究，本项目使用独立编写的 Canvas 实现。液态波纹是正弦位移，不是流体物理模拟。</p><h3>方法参考</h3><ul><li><a target="_blank" rel="noopener" href="https://blog.maximeheckel.com/posts/the-art-of-dithering-and-retro-shading-web/">Bayer 抖色与复古图像处理</a></li><li><a target="_blank" rel="noopener" href="https://helpx.adobe.com/photoshop/using/filter-effects-reference.html">Adobe 滤镜行为参考</a></li><li><a target="_blank" rel="noopener" href="https://maximmcnair.com/webgl-image-processing">图像处理与混合模式</a></li><li><a target="_blank" rel="noopener" href="https://www.shutterevolve.com/create-orton-effect-photoshop/">Orton 柔焦思路</a></li></ul><h3>本版边界</h3><p>胶片、CRT、蓝晒为视觉近似。色相循环不是索引色循环；局部色光是二维叠加；双色刊物是网点配色，并非真实印刷分色。当前不包含 AI 抠图、笔刷绘制蒙版、CUBE 导入或视频源处理；动图导出为自研 GIF 编码，视频导出为无声 WebM。</p>`);
const area=$('dropArea');area.ondragover=e=>{e.preventDefault();area.classList.add('dragover')};area.ondragleave=()=>area.classList.remove('dragover');area.ondrop=e=>{e.preventDefault();area.classList.remove('dragover');const f=e.dataTransfer.files[0];if(f?.name.endsWith('.json'))loadProject(f);else{importMode='base';importImage(f)}};
document.addEventListener('keydown',e=>{if(['INPUT','TEXTAREA','SELECT'].includes(document.activeElement.tagName)||document.querySelector('dialog[open]'))return;if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='z'){e.preventDefault();undoAction(e.shiftKey)}if(e.code==='Space'){e.preventDefault();playing=!playing;playStart=0}});window.addEventListener('resize',()=>dirty=true);window.addEventListener('beforeunload',e=>{if(draftFailed){e.preventDefault();e.returnValue=''}});
async function restoreDraft(){try{const raw=await loadDraft();if(!raw)return null;const v=validateProject(raw);delete v.app;await Promise.all(v.layers.filter(l=>l.type==='image').map(l=>imageLoad(l.src)));return v}catch{return null}}
async function init(){const draft=await restoreDraft();if(draft){state=draft;selected=state.layers.at(-1)?.id;savedState=JSON.stringify(state);hydrate();updateTab();draw();requestAnimationFrame(loop);tell('已恢复上次编辑 · 用「打开」可载入其他工程');return}try{await imageLoad('demo-photo.jpg');state.layers=[baseLayer('image',{name:'旷野来信 · Unsplash',src:'demo-photo.jpg',w:1600,h:2400,y:500})];selected=state.layers[0].id;savedState=JSON.stringify(state);hydrate();updateTab();draw();requestAnimationFrame(loop)}catch(e){tell('示例加载失败，请导入照片开始');hydrate();updateTab();requestAnimationFrame(loop)}}init();

function setPanel(panel){document.body.dataset.panel=panel;document.querySelectorAll('[data-panel]').forEach(b=>{if(b.tagName==='BUTTON'){b.classList.toggle('active',b.dataset.panel===panel);b.setAttribute('aria-pressed',b.dataset.panel===panel)}})}
document.querySelectorAll('.inspector-tabs button').forEach(b=>b.onclick=()=>setPanel(b.dataset.panel));
$('focusMode').onclick=()=>{const on=document.body.classList.toggle('focus-mode');$('focusMode').setAttribute('aria-pressed',on);$('focusMode').textContent=on?'退出专注 ↙':'专注模式 ⤢';dirty=true};
$('expandLibrary').onclick=()=>{const on=document.body.classList.toggle('library-expanded');$('expandLibrary').setAttribute('aria-expanded',on);$('expandLibrary').textContent=on?'收起档案 ↙':'展开全部 ↗';dirty=true};

// Exhibition and utility controls share the same document and renderer as export.
let galleryCategory='全部',galleryRenderToken=0;
let favoritesOnly=false,lookIndex=0,lookOriginal=false,lookSnapshot=null;
let favoriteLooks=[];try{const f=JSON.parse(localStorage.getItem('afterimage-favorite-looks')||'[]');if(Array.isArray(f))favoriteLooks=f.filter(v=>typeof v==='string')}catch{}
const galleryRecipes=()=>PRESETS.filter(p=>(!favoritesOnly||favoriteLooks.includes(p.en))&&(galleryCategory==='全部'||p.cat===galleryCategory)&&`${p.name} ${p.en} ${p.desc||''}`.toLowerCase().includes($('gallerySearch').value.toLowerCase()));
function setPicked(hex){if(!/^#[0-9a-f]{6}$/i.test(hex))return;$('pickedHex').value=hex.toUpperCase();$('pickedChip').style.background=hex;$('paletteColor').value=hex.toLowerCase()}
$('eyedropper').onclick=()=>{picking=!picking;$('eyedropper').setAttribute('aria-pressed',picking);updateSelection();cv.style.cursor=picking?'crosshair':'grab';if(picking)tell('点击画布采样颜色；再次点取色可取消')};
$('comparePosition').oninput=e=>{comparePosition=Number(e.target.value)/100;dirty=true};
$('applyPicked').onclick=()=>{const layer=state.layers.find(l=>l.id===selected);if(!layer||layer.type==='image'){tell('请先选择文字、符号或形状图层');return}if(layer.locked){tell('请先解锁图层');return}checkpoint();layer.color=$('pickedHex').value;renderProps();change();tell('图层颜色已更新')};
$('extractPalette').onclick=()=>{const out=render(state,assets,160,time),d=out.getContext('2d').getImageData(0,0,out.width,out.height).data,bins=new Map();for(let i=0;i<d.length;i+=4){if(d[i+3]<128)continue;const q=[d[i],d[i+1],d[i+2]].map(v=>Math.floor(v/32)),key=q.join(',');let bin=bins.get(key);if(!bin){bin={n:0,sum:[0,0,0]};bins.set(key,bin)}bin.n++;for(let j=0;j<3;j++)bin.sum[j]+=d[i+j]}const colors=[...bins.values()].sort((a,b)=>b.n-a.n).slice(0,8).map(b=>'#'+b.sum.map(v=>Math.round(v/b.n).toString(16).padStart(2,'0')).join(''));$('paletteSwatches').innerHTML=colors.map(hex=>`<button title="选择 ${hex}" aria-label="选择颜色 ${hex}" data-hex="${hex}" style="background:${hex}"></button>`).join('');$('paletteSwatches').querySelectorAll('button').forEach(b=>b.onclick=()=>setPicked(b.dataset.hex));tell(colors.length?'已提取当前画面的主色':'画面没有可见颜色')};
$('randomLook').onclick=()=>{const list=PRESETS.filter(p=>p.name!==state.recipe);applyPreset(list[Math.floor(Math.random()*list.length)]);tab='presets';category='全部';updateTab()};
function galleryFilters(){$('galleryFilter').innerHTML=FAMILIES.map(cat=>`<button class="${cat===galleryCategory?'active':''}" data-gallery-cat="${cat}">${cat}<span>${cat==='全部'?PRESETS.length:PRESETS.filter(p=>p.cat===cat).length}</span></button>`).join('');$('galleryFilter').querySelectorAll('button').forEach(b=>b.onclick=()=>{galleryCategory=b.dataset.galleryCat;galleryFilters();renderGallery()})}
async function renderGallery(){const token=++galleryRenderToken,grid=$('galleryGrid');grid.innerHTML='';const snapshot=JSON.parse(JSON.stringify(state)),frameTime=time,list=galleryRecipes();$('galleryResultCount').textContent=list.length+' / '+PRESETS.length+' LOOKS';if(!list.length){grid.innerHTML='<p class="gallery-empty">没有匹配的风格，试试其他关键词。</p>';return}for(const [i,p] of list.entries()){if(token!==galleryRenderToken||!$('galleryDialog').open)return;const b=document.createElement('button');b.className='gallery-card';b.style.setProperty('--i',i);b.innerHTML=`<div class="gallery-image"><canvas></canvas><span class="try-look">进入试映 ↗</span></div><div class="gallery-meta"><span>${String(PRESETS.indexOf(p)+1).padStart(2,'0')} / ${p.cat}</span><span>↗</span></div><h3>${esc(p.en)}</h3><p>${esc(p.name)}</p><small class="look-description">${esc(p.desc||p.chain.map(e=>EFFECTS[e.type].name).join(' · '))}</small>`;grid.append(b);const out=render(recipeDocument(snapshot,p),assets,144,frameTime),c=b.querySelector('canvas');c.width=out.width;c.height=out.height;c.getContext('2d').drawImage(out,0,0);b.onclick=()=>openLook(p);await new Promise(r=>setTimeout(r,0))}}
function syncGalleryCounts(){const n=PRESETS.length,kicker=$('galleryKicker'),sub=$('gallerySubCount');if(kicker)kicker.textContent=`VOL. 08 / THE IMAGE CULTURE ISSUE / ${n} LOOKS`;if(sub)sub.textContent=`${n} 种成品配方。摄影、纸墨、旧屏幕，以及意料之外。`}
$('galleryOpen').onclick=()=>{playing=false;syncGalleryCounts();galleryFilters();$('galleryDialog').showModal();renderFeatured();renderGallery()};
$('galleryClose').onclick=()=>{$('galleryDialog').close();galleryRenderToken++};
$('contactSheet').onclick=async()=>{const button=$('contactSheet');button.disabled=true;button.textContent='正在生成…';try{const list=galleryRecipes();if(!list.length){tell('没有匹配的风格，请修改搜索词');return}const snapshot=JSON.parse(JSON.stringify(state)),frameTime=time,cols=4,cellW=360,cellH=260,pad=24,head=112,c=newCanvas(cols*cellW+pad*2,Math.ceil(list.length/cols)*cellH+head+pad),x=c.getContext('2d');x.fillStyle='#e9e7df';x.fillRect(0,0,c.width,c.height);x.fillStyle='#171916';x.font='bold 45px sans-serif';x.fillText('AFTERIMAGE / CONTACT SHEET',pad,58);x.font='14px sans-serif';x.fillText('余像 · '+snapshot.title+' / '+list.length+' LOOKS',pad,88);for(let i=0;i<list.length;i++){const p=list[i],out=render(recipeDocument(snapshot,p),assets,600,frameTime),left=pad+(i%cols)*cellW,top=head+Math.floor(i/cols)*cellH,scale=Math.min((cellW-18)/out.width,190/out.height);x.fillStyle='#161b13';x.fillRect(left,top,cellW-18,190);x.drawImage(out,left+(cellW-18-out.width*scale)/2,top+(190-out.height*scale)/2,out.width*scale,out.height*scale);x.fillStyle='#171916';x.font='bold 15px sans-serif';x.fillText(p.name,left,top+215);x.font='11px monospace';x.fillText(p.en,left,top+236);await new Promise(r=>setTimeout(r,0))}const blob=await new Promise(r=>c.toBlob(r,'image/png'));if(!blob)throw new Error('编码失败');download(blob,'余像-风格联系表.png');tell('风格联系表已下载')}catch(e){tell('联系表生成失败：'+e.message)}finally{button.disabled=false;button.textContent='下载风格联系表 ↗'}};
function effectTarget(){if($('effectScope').value==='all')return 'all';if(!state.layers.some(l=>l.id===selected)){tell('先选中一个图层，再添加效果');return null}return selected}
function recipeDocument(doc,recipe){const target=$('effectScope').value==='all'?'all':selected;if(!target)return doc;return {...doc,effects:doc.effects.filter(e=>e.target!==target).concat(buildChain(recipe).map(e=>({...e,target})))}}
$('effectScope').onchange=()=>{updateLabels();renderLibrary()};
function renderProps(){renderBaseProps();renderEditorExtras();renderEditingTools();renderTemplateFields();updateSelection()}
function curveMarkup(e){return `<svg class="curve-editor" viewBox="-8 -8 272 272" role="img" aria-label="五点曲线，拖动控制点调整输出"><path class="curve-grid" d="M0 0V255H255V0Z M64 0V255 M128 0V255 M192 0V255 M0 64H255 M0 128H255 M0 192H255"/><path class="curve-diagonal" d="M0 255L255 0"/><polyline class="curve-line"/>${['black','shadows','mid','highlights','white'].map((key,i)=>`<circle data-curve="${key}" cx="${[0,64,128,192,255][i]}" cy="${255-e.params[key]}" r="6"/>`).join('')}</svg>`}
function refreshCurve(box,e){const svg=box.querySelector('.curve-editor');if(!svg)return;const keys=['black','shadows','mid','highlights','white'];svg.querySelector('.curve-line').setAttribute('points',keys.map((key,i)=>`${[0,64,128,192,255][i]},${255-e.params[key]}`).join(' '));keys.forEach(key=>svg.querySelector(`[data-curve="${key}"]`).setAttribute('cy',255-e.params[key]))}
function wireCurve(box,e){const svg=box.querySelector('.curve-editor');if(!svg)return;refreshCurve(box,e);let key=null;svg.onpointerdown=event=>{key=event.target.dataset.curve;if(!key)return;checkpoint();svg.setPointerCapture(event.pointerId);event.preventDefault()};svg.onpointermove=event=>{if(!key)return;const r=svg.getBoundingClientRect(),value=Math.round(Math.max(0,Math.min(255,255-((event.clientY-r.top)/r.height*272-8))));e.params[key]=value;const input=box.querySelector(`[data-key="${key}"]`);input.value=value;input.previousElementSibling.querySelector('output').textContent=value;refreshCurve(box,e);state.recipe='自定义配方';change()};svg.onpointerup=()=>key=null;svg.onpointercancel=()=>key=null}
function renderEditorExtras(){const host=$('editorExtras'),l=state.layers.find(l=>l.id===selected);if(!l){host.innerHTML='';return}const m=l.mask||{type:'none',x:50,y:50,w:100,h:100,feather:0,invert:false},motion=l.motion||{enabled:false,dx:0,dy:0,rotation:0,scale:100};
 const number=(group,key,label,value,min,max,step=1)=>`<label>${label}<input type="number" data-group="${group}" data-field="${key}" value="${value}" min="${min}" max="${max}" step="${step}"></label>`;
 host.innerHTML=`<details class="editor-section" open><summary>排版与对齐 <span>LAYOUT</span></summary><div class="align-tools"><button data-align="left">靠左</button><button data-align="centerX">水平居中</button><button data-align="right">靠右</button><button data-align="top">靠上</button><button data-align="centerY">垂直居中</button><button data-align="bottom">靠下</button></div>${l.type==='text'?`<div class="props-grid"><label>段落对齐<select data-group="text" data-field="align"><option value="left">左对齐</option><option value="center">居中</option><option value="right">右对齐</option></select></label><label>自动换行<select data-group="text" data-field="wrap"><option value="true">按文本框宽度</option><option value="false">仅手动换行</option></select></label>${number('text','lineHeight','行距倍数',l.lineHeight||1.35,.5,3,.05)}${number('text','textScaleX','字形横向宽度',l.textScaleX||1,.2,3,.01)}${number('text','glow','发光半径 px',l.glow||0,0,100)}<label>发光颜色<input type="color" data-group="text" data-field="glowColor" value="${l.glowColor||l.color||'#ffffff'}"></label></div>`:''}</details><details class="editor-section" open><summary>图层蒙版 <span>MASK</span></summary><label class="field">形状<select data-group="mask" data-field="type"><option value="none">无蒙版</option><option value="ellipse">椭圆</option><option value="rect">矩形</option></select></label><div class="props-grid">${number('mask','x','中心 X %',m.x,-100,200)}${number('mask','y','中心 Y %',m.y,-100,200)}${number('mask','w','宽度 %',m.w,1,200)}${number('mask','h','高度 %',m.h,1,200)}${number('mask','feather','羽化 px',m.feather,0,200)}<label>反相<select data-group="mask" data-field="invert"><option value="false">保留内部</option><option value="true">挖空内部</option></select></label></div><p class="editor-note">蒙版跟随图层移动；参数相对图层尺寸。原图保留。</p></details><details class="editor-section" open><summary>图层运动 <span>MOTION</span></summary><label class="field">循环<select data-group="motion" data-field="enabled"><option value="false">关闭</option><option value="true">往返 · 缓入缓出</option></select></label><div class="props-grid">${number('motion','dx','横向位移 px',motion.dx,-4096,4096)}${number('motion','dy','纵向位移 px',motion.dy,-4096,4096)}${number('motion','rotation','旋转增量 °',motion.rotation,-360,360)}${number('motion','scale','终点大小 %',motion.scale,10,300)}</div><p class="editor-note">0 秒为起点，时长一半到终点，再返回。拖动边框会回到起点编辑。</p><button id="previewLayerMotion" class="motion-preview">▶ 预览运动</button></details>`;
 host.querySelectorAll('[data-group]').forEach(input=>{const group=input.dataset.group,key=input.dataset.field;if(input.tagName==='SELECT')input.value=String(group==='text'?(key==='align'?l.align||'center':l.wrap!==false):group==='mask'?m[key]:motion[key]);input.disabled=l.locked;let began=false;const update=()=>{if(!began){checkpoint();began=true}let value=input.type==='number'?Math.min(Number(input.max),Math.max(Number(input.min),Number(input.value)||0)):['enabled','invert','wrap'].includes(key)?input.value==='true':input.value;if(group==='text'){l[key]=value;fitTextHeight(l);}else{if(!l[group])l[group]={...(group==='mask'?m:motion)};l[group][key]=value}change()};input.oninput=update;input.onchange=()=>{update();began=false};input.onblur=()=>began=false});
 host.querySelectorAll('[data-align]').forEach(b=>b.onclick=()=>{if(l.locked){tell('请先解锁图层');return}checkpoint();const action=b.dataset.align,bx=l.x,by=l.y;if(action==='left')l.x=l.w/2;if(action==='right')l.x=state.width-l.w/2;if(action==='top')l.y=l.h/2;if(action==='bottom')l.y=state.height-l.h/2;if(action==='centerX')l.x=state.width/2;if(action==='centerY')l.y=state.height/2;if(l.x!==bx||l.y!==by)shiftKeyframes(l,l.x-bx,l.y-by);time=0;playing=false;hydrate()});
 $('previewLayerMotion').onclick=()=>{if(!l.motion?.enabled){tell('先开启图层往返循环');return}playing=true;playStart=0;time=0;dirty=true};
}
