let transformDrag=null;
$('selectionOverlay').querySelectorAll('[data-transform]').forEach(handle=>{handle.onpointerdown=event=>{const l=state.layers.find(l=>l.id===selected);if(!l||l.locked||!canMoveGroup(l))return;groupDrag=groupSnapshot(l);event.stopPropagation();event.preventDefault();playing=false;playStart=0;checkpoint();const r=cv.getBoundingClientRect(),mx=(event.clientX-r.left)/r.width*state.width,my=(event.clientY-r.top)/r.height*state.height;transformDrag={layer:l,kind:handle.dataset.transform,x:mx,y:my,rotation:l.rotation,w:l.w,h:l.h,fontSize:l.fontSize,distance:Math.max(1,Math.hypot(mx-l.x,my-l.y)),angle:Math.atan2(my-l.y,mx-l.x)};handle.setPointerCapture(event.pointerId);dirty=true};handle.onpointermove=event=>{if(!transformDrag)return;const d=transformDrag,r=cv.getBoundingClientRect(),mx=(event.clientX-r.left)/r.width*state.width,my=(event.clientY-r.top)/r.height*state.height;if(d.kind==='rotate'){let angle=d.rotation+(Math.atan2(my-d.layer.y,mx-d.layer.x)-d.angle)*180/Math.PI;if(event.shiftKey)angle=Math.round(angle/15)*15;const next=((angle+540)%360)-180,drot=next-d.layer.rotation;d.layer.rotation=next;if(drot)shiftKeyframes(d.layer,0,0,drot)}else{const scale=Math.max(.05,Math.min(10,Math.hypot(mx-d.layer.x,my-d.layer.y)/d.distance)),factor=Math.min(scale,32768/d.w,32768/d.h);d.layer.w=Math.max(1,d.w*factor);d.layer.h=Math.max(1,d.h*factor);if(d.fontSize)d.layer.fontSize=Math.max(8,Math.min(600,d.fontSize*factor))}if(groupDrag)transformMembers(state.layers,groupDrag,d.layer.id);dirty=true;updateSelection()};handle.onpointerup=()=>{if(transformDrag){transformDrag=null;renderProps();change()}};handle.onpointercancel=()=>{transformDrag=null;renderProps();change()}});
function hideInline(){const ta=$('inlineEditor');if(!ta||ta.hidden)return;try{ta.blur()}catch{ta.hidden=true}}
function startInlineEdit(l){if(!l||l.locked||(l.type!=='text'&&l.type!=='sticker'))return;const ta=$('inlineEditor'),pose=layerPose(l,time,state.duration),sx=cv.clientWidth/state.width,sy=cv.clientHeight/state.height,px=Math.max(8,Math.round((l.fontSize||20)*sy));ta.style.left=Math.max(0,pose.x*sx-pose.w*sx/2)+'px';ta.style.top=Math.max(0,pose.y*sy-pose.h*sy/2)+'px';ta.style.width=Math.max(60,pose.w*sx)+'px';ta.style.height=Math.max(26,pose.h*sy)+'px';ta.style.font=`${l.weight||700} ${px}px ${l.font||'sans-serif'}`;ta.style.lineHeight=String(l.lineHeight||1.35);ta.style.color=l.color||'#ecf1d4';ta.style.textAlign=l.align||'left';ta.value=l.content||'';ta.hidden=false;try{ta.focus();ta.select()}catch{}let begun=false;ta.oninput=()=>{if(!begun){checkpoint();begun=true}l.content=ta.value;fitTextHeight(l);ta.style.height=Math.max(26,l.h*sy)+'px';dirty=true};ta.onblur=()=>{if(ta.hidden)return;ta.hidden=true;change()};ta.onkeydown=e=>{if(e.key==='Escape'){e.preventDefault();ta.blur()}if((e.ctrlKey||e.metaKey)&&e.key==='Enter'){e.preventDefault();ta.blur()}}}
$('selectionToolbar').addEventListener('click',ev=>{const btn=ev.target.closest('[data-tool]');if(!btn)return;const l=state.layers.find(x=>x.id===selected);if(!l||l.locked)return;const tool=btn.dataset.tool;if(tool==='editText'){startInlineEdit(l);return}if(tool==='opacityUp'||tool==='opacityDown'){checkpoint();l.opacity=Math.max(0,Math.min(100,l.opacity+(tool==='opacityUp'?10:-10)));renderProps();change();tell('不透明度 '+Math.round(l.opacity)+'%');return}const action=tool==='duplicate'?'copy':'delete';$('layerProps').querySelector(`[data-layer="${action}"]`)?.click()});
