function showSavedColors(){$('savedSwatches').innerHTML=savedColors.map(hex=>`<button style="background:${hex}" title="${hex} · 选择颜色" aria-label="收藏颜色 ${hex}" data-hex="${hex}"></button>`).join('');$('savedSwatches').querySelectorAll('button').forEach(b=>b.onclick=()=>setPicked(b.dataset.hex))}
