document.addEventListener('keydown',event=>{if(['INPUT','TEXTAREA','SELECT'].includes(document.activeElement.tagName)||document.querySelector('dialog[open]'))return;const l=state.layers.find(l=>l.id===selected);if(event.key==='Escape'){cropMode=false;panMode=false;picking=false;$('eyedropper').setAttribute('aria-pressed','false');cv.style.cursor='grab';selected=null;renderProps();return}if(!l||l.locked)return;if(['ArrowLeft','ArrowRight','ArrowUp','ArrowDown'].includes(event.key)){event.preventDefault();if(!event.repeat)checkpoint();const step=event.shiftKey?10:1;l.x+=event.key==='ArrowLeft'?-step:event.key==='ArrowRight'?step:0;l.y+=event.key==='ArrowUp'?-step:event.key==='ArrowDown'?step:0;playing=false;renderProps();change()}if(event.key==='Delete'||event.key==='Backspace'){event.preventDefault();$('layerProps').querySelector('[data-layer="delete"]')?.click()}if((event.ctrlKey||event.metaKey)&&event.key.toLowerCase()==='d'){event.preventDefault();$('layerProps').querySelector('[data-layer="copy"]')?.click()}});

