$('galleryTheme').onclick=()=>{const dark=$('galleryDialog').classList.toggle('gallery-dark');$('galleryTheme').setAttribute('aria-pressed',dark)};
$('galleryView').onclick=()=>{const index=$('galleryGrid').classList.toggle('index-view');$('galleryView').setAttribute('aria-pressed',index);$('galleryView').textContent=index?'▦ 海报视图':'☷ 索引视图'};

