$('lookFavorite').onclick=()=>{const key=PRESETS[lookIndex].en;favoriteLooks=favoriteLooks.includes(key)?favoriteLooks.filter(v=>v!==key):[...favoriteLooks,key];try{localStorage.setItem('afterimage-favorite-looks',JSON.stringify(favoriteLooks))}catch{tell('浏览器存储不可用，本次收藏仍可使用')}renderLook();if(favoritesOnly)renderGallery()};
$('lookPrevious').onclick=()=>{lookIndex=(lookIndex-1+PRESETS.length)%PRESETS.length;lookOriginal=false;renderLook()};
$('lookNext').onclick=()=>{lookIndex=(lookIndex+1)%PRESETS.length;lookOriginal=false;renderLook()};
$('lookApply').onclick=()=>{applyPreset(PRESETS[lookIndex]);$('lookDialog').close();$('galleryDialog').close();galleryRenderToken++;tab='presets';category='全部';updateTab()};
$('favoritesOnly').onclick=()=>{favoritesOnly=!favoritesOnly;$('favoritesOnly').setAttribute('aria-pressed',favoritesOnly);$('favoritesOnly').textContent=favoritesOnly?'♥ 我的收藏':'♡ 只看收藏';renderGallery()};

function seek(seconds){playing=false;playStart=0;time=Math.max(0,Math.min(state.duration-.001,seconds));dirty=true;updatePlayhead()}
function updatePlayhead(){const host=$('timelineTracks');if(host)host.style.setProperty('--playhead',(time/state.duration*100)+'%')}
function timingFor(l){return l.timing??(l.timing={start:0,end:state.duration,fadeIn:0,fadeOut:0})}
function renderTimeline(){const host=$('timelineTracks');if(!host)return;host.innerHTML=state.layers.slice().reverse().map(l=>{const r=clipRange(l,state.duration);return `<div class="timeline-row ${l.id===selected?'selected':''}"><button class="track-name" data-select="${l.id}">${esc(l.name)}</button><div class="track-lane" data-lane="${l.id}"><div class="clip" data-clip="${l.id}" style="left:${r.start/state.duration*100}%;width:${(r.end-r.start)/state.duration*100}%"><button data-trim="start" aria-label="裁剪入点"></button><span>${r.start.toFixed(1)}—${r.end.toFixed(1)}s</span><button data-trim="end" aria-label="裁剪出点"></button></div>${(l.keyframes||[]).map((k,i)=>`<button class="kf" data-kfseek="${l.id}:${i}" style="left:${Math.max(0,Math.min(100,k.t/state.duration*100))}%" title="关键帧 ${k.t.toFixed(2)}s"></button>`).join('')}<i class="track-playhead"></i></div></div>`}).join('');
 const l=state.layers.find(l=>l.id===selected),r=l?clipRange(l,state.duration):{start:0,end:state.duration};for(const [id,value] of [['clipStart',r.start],['clipEnd',r.end],['clipFadeIn',l?.timing?.fadeIn||0],['clipFadeOut',l?.timing?.fadeOut||0]]){$(id).value=value;$(id).disabled=!l||l.locked;$(id).max=state.duration}host.querySelectorAll('[data-select]').forEach(b=>b.onclick=()=>{selected=b.dataset.select;hydrate()});host.querySelectorAll('[data-kfseek]').forEach(b=>{const [id,index]=b.dataset.kfseek.split(':');b.onclick=e=>{e.stopPropagation();const layer=state.layers.find(x=>x.id===id);selected=id;if(layer?.keyframes?.[index])seek(layer.keyframes[index].t);hydrate()}});host.querySelectorAll('[data-lane]').forEach(lane=>{lane.onpointerdown=e=>{if(e.target.closest('[data-clip]'))return;const r=lane.getBoundingClientRect();seek((e.clientX-r.left)/r.width*state.duration)}});
 host.querySelectorAll('[data-clip]').forEach(clip=>{clip.onpointerdown=e=>{const l=state.layers.find(l=>l.id===clip.dataset.clip);if(!l||l.locked)return;e.preventDefault();e.stopPropagation();selected=l.id;playing=false;playStart=0;checkpoint();const z=timingFor(l),start={...z},px=e.clientX,rect=clip.parentElement.getBoundingClientRect(),kind=e.target.dataset.trim;clip.setPointerCapture(e.pointerId);clip.onpointermove=ev=>{const d=Math.round((ev.clientX-px)/rect.width*state.duration*20)/20;if(kind==='start')z.start=Math.max(0,Math.min(start.end-.05,start.start+d));else if(kind==='end')z.end=Math.min(state.duration,Math.max(start.start+.05,start.end+d));else{z.start=Math.max(0,Math.min(state.duration-(start.end-start.start),start.start+d));z.end=z.start+start.end-start.start}clip.style.left=z.start/state.duration*100+'%';clip.style.width=(z.end-z.start)/state.duration*100+'%';clip.querySelector('span').textContent=z.start.toFixed(2)+'—'+z.end.toFixed(2)+'s';dirty=true};clip.onpointerup=clip.onpointercancel=()=>{clip.onpointermove=null;hydrate()}}});renderKeyframes(l);updatePlayhead()}
function sortedKeys(l){return (l?.keyframes||[]).slice().sort((a,b)=>a.t-b.t)}
function nearestKey(l){const keys=sortedKeys(l);if(!keys.length)return -1;let best=0;keys.forEach((k,i)=>{if(Math.abs(k.t-time)<Math.abs(keys[best].t-time))best=i});return best}
function addKeyframe(){const l=state.layers.find(l=>l.id===selected);if(!l||l.locked)return;checkpoint();const t=Math.round(time*100)/100,pose=layerPose(l,t,state.duration),keys=sortedKeys(l).filter(k=>Math.abs(k.t-t)>.03);keys.push({t,x:Math.round(pose.x*100)/100,y:Math.round(pose.y*100)/100,rotation:Math.round(pose.rotation*100)/100,scale:Math.round(pose.w/Math.max(1,l.w)*1e4)/100,opacity:Math.round(pose.opacity*100)/100,ease:'smooth'});keys.sort((a,b)=>a.t-b.t);l.keyframes=keys;if(l.motion)l.motion.enabled=false;change();tell(`已在 ${t.toFixed(2)} 秒记录关键帧`)}
function deleteKeyframe(index){const l=state.layers.find(l=>l.id===selected),keys=sortedKeys(l);if(!l||l.locked||index<0||index>=keys.length)return;checkpoint();keys.splice(index,1);if(keys.length)l.keyframes=keys;else delete l.keyframes;change()}
function renderKeyframes(l){
 const host=$('keyframeBar');if(!host)return;
 const keys=sortedKeys(l),near=nearestKey(l);
 host.innerHTML=`<div class="kf-tools"><button id="kfAdd" title="在当前播放头记录图层的位置、旋转、缩放与不透明度">◆ 打关键帧</button><label>缓动<select id="kfEase" aria-label="当前关键帧缓动"><option value="smooth">平滑</option><option value="linear">线性</option><option value="hold">定格</option></select></label><span class="kf-count">${keys.length} 帧${keys.length>1?' · 覆盖运动预设':''}</span></div><div class="kf-list">${keys.length?keys.map((k,i)=>`<span class="kf-chip${i===near?' near':''}"><button class="kf-goto" data-kfseek="${i}" title="跳到 ${k.t.toFixed(2)} 秒">◆ ${k.t.toFixed(2)}s</button><button class="kf-del" data-kfdel="${i}" title="删除这一帧">×</button></span>`).join(''):'<span class="kf-empty">还没有关键帧：把播放头移到想记录的时刻，点「打关键帧」。</span>'}</div>${keys.length?`<div class="kf-fields"><span>当前帧数值</span>${[['x','X px',-32768,32768,1],['y','Y px',-32768,32768,1],['rotation','旋转 °',-360,360,1],['scale','缩放 %',10,3000,1],['opacity','透明 %',0,100,1]].map(([key,label,min,max,step])=>`<label>${label}<input type="number" data-kfield="${key}" value="${Math.round((keys[near]?.[key]??0)*100)/100}" min="${min}" max="${max}" step="${step}"></label>`).join('')}</div>`:''}`;
 $('kfEase').disabled=!keys.length;$('kfAdd').disabled=!l||l.locked;
 if(keys.length)$('kfEase').value=keys[near]?.ease||'smooth';
 $('kfAdd').onclick=()=>addKeyframe();
 $('kfEase').onchange=()=>{const layer=state.layers.find(x=>x.id===selected),index=nearestKey(layer);if(!layer||layer.locked||index<0)return;const all=sortedKeys(layer);all[index].ease=$('kfEase').value;layer.keyframes=all;change();tell(`第 ${index+1} 个关键帧改用${$('kfEase').selectedOptions[0].textContent}缓动`)};
 host.querySelectorAll('[data-kfdel]').forEach(b=>b.onclick=e=>{e.stopPropagation();deleteKeyframe(Number(b.dataset.kfdel))});
 host.querySelectorAll('[data-kfseek]').forEach(b=>b.onclick=e=>{e.stopPropagation();const k=keys[Number(b.dataset.kfseek)];if(k)seek(k.t)});
 host.querySelectorAll('[data-kfield]').forEach(input=>{let began=false;const write=()=>{const layer=state.layers.find(x=>x.id===selected),index=nearestKey(layer);if(!layer||layer.locked||index<0)return;if(!began){checkpoint();began=true}const all=sortedKeys(layer),v=Math.max(Number(input.min),Math.min(Number(input.max),Number(input.value)||0));all[index][input.dataset.kfield]=Math.round(v*100)/100;layer.keyframes=all;dirty=true;persistDraft()};input.oninput=write;input.onchange=()=>{write();began=false};input.onblur=()=>began=false});
}
for(const [id,key] of [['clipStart','start'],['clipEnd','end'],['clipFadeIn','fadeIn'],['clipFadeOut','fadeOut']])$(id).onchange=()=>{const l=state.layers.find(l=>l.id===selected);if(!l||l.locked)return;const v=Number($(id).value);if(!Number.isFinite(v))return;checkpoint();const z=timingFor(l);z[key]=Math.max(0,Math.min(state.duration,v));if(key==='start')z.start=Math.min(z.start,z.end-.05);if(key==='end')z.end=Math.max(z.end,z.start+.05);change()};
$('clipStartAt').onclick=()=>{$('clipStart').value=time;$('clipStart').onchange()};$('clipEndAt').onclick=()=>{$('clipEnd').value=time;$('clipEnd').onchange()};
$('frameBack').onclick=()=>seek(time-1/30);$('frameNext').onclick=()=>seek(time+1/30);
$('previewQuality').onchange=()=>{dirty=true};$('timelineToggle').onclick=()=>{const p=$('timelinePanel');p.hidden=!p.hidden;$('timelineToggle').setAttribute('aria-expanded',!p.hidden);dirty=true};
$('motionQuick').onchange=()=>{const l=state.layers.find(l=>l.id===selected),v=$('motionQuick').value;if(!l||l.locked||!v)return;checkpoint();const z=timingFor(l);l.motion={enabled:v!=='none'&&v!=='fade',dx:0,dy:v==='float'?-45:0,rotation:v==='swing'?12:0,scale:v==='zoom'?118:100};z.fadeIn=v==='fade'?.5:0;z.fadeOut=v==='fade'?.5:0;$('motionQuick').value='';hydrate()};

function renderTemplates(host,q){host.innerHTML='<p class="template-note">成片模板会重排当前作品，可撤销。使用选中照片；贴片直接叠加。每个文字和形状都可编辑。</p><div class="template-grid"></div>';const grid=host.lastElementChild,tsig=thumbSignature();for(const [key,name,desc] of TEMPLATES){if(!(name+desc).toLowerCase().includes(q))continue;const b=document.createElement('button');b.className='template-card';b.innerHTML=`<canvas></canvas><strong>${esc(name)}</strong><small>${esc(desc)}</small>`;grid.append(b);const source=state.layers.find(l=>l.id===selected&&l.type==='image')||state.layers.find(l=>l.type==='image');const tkey=key+'|'+(source?.id||'none')+'|'+tsig;let out=templateCache.get(tkey);if(!out){const draft=composeTemplate(key,source,baseLayer);out=render({...state,...draft},assets,144,0);templateCache.set(tkey,out);if(templateCache.size>120)templateCache.clear()}const cv=b.querySelector('canvas');cv.width=out.width;cv.height=out.height;cv.getContext('2d').drawImage(out,0,0);b.onclick=()=>{if(!source&&key!=='eva'){tell('请先导入一张照片');return}checkpoint();Object.assign(state,composeTemplate(key,source,baseLayer),{recipe:name,title:name,template:key});time=0;playing=false;selected=state.layers.find(l=>l.type==='image'&&!l.hidden)?.id||state.layers.find(l=>l.type==='text')?.id||state.layers.at(-1)?.id;hydrate();setPanel('layers');tell('模板已应用 · 可撤销，文字和照片分别编辑');};}const footer=document.createElement('div');footer.className='patch-tools';footer.innerHTML='<h3>直接叠加 / PATCHES</h3>'+PATCHES.map(([k,n])=>`<button data-patch="${k}">＋ ${n}</button>`).join('')+'<button id="softEdge">◌ 选中图层边缘羽化</button>';host.append(footer);footer.querySelectorAll('[data-patch]').forEach(b=>b.onclick=()=>{const a=composePatch(b.dataset.patch,state.width,state.height,baseLayer),groupId=crypto.randomUUID();a.forEach(l=>l.groupId=groupId);if(state.layers.length+a.length>60){tell('图层已达上限，请先删除部分图层');return}checkpoint();state.layers.push(...a);selected=a.at(-1).id;hydrate();setPanel('layers')});footer.querySelector('#softEdge').onclick=()=>{const l=state.layers.find(l=>l.id===selected);if(!l||l.locked){tell('请选择一个未锁定图层');return}checkpoint();l.mask={type:'rect',x:50,y:50,w:90,h:90,feather:Math.min(200,Math.min(l.w,l.h)*.05),invert:false};hydrate();setPanel('layers');tell('已添加羽化蒙版，可在图层蒙版中调节')};}

function groupSnapshot(l){return groupMode&&l.groupId?state.layers.filter(x=>x.groupId===l.groupId).map(x=>JSON.parse(JSON.stringify(x))):null}
function canMoveGroup(l){if(groupMode&&l.groupId&&state.layers.some(x=>x.groupId===l.groupId&&x.locked)){tell('组内包含锁定图层，请解锁或关闭整组变换');return false}return true}
function renderEditingTools(){let host=$('editingTools');if(!host){host=document.createElement('section');host.id='editingTools';$('layerProps').before(host)}const l=state.layers.find(x=>x.id===selected);if(!l){host.innerHTML='';return}host.innerHTML=`<details open><summary>快速编辑 / QUICK EDIT</summary>${l.type==='image'?`<button id="cropToggle">${cropMode?'✓ 完成框内构图':'▧ 调整框内照片'}</button><label>照片缩放 <input id="cropZoom" type="range" min="1" max="5" step="0.01" value="${l.crop?.zoom||1}"></label><button id="cropReset">重置构图</button>`:''}<label><input id="groupMode" type="checkbox" ${groupMode?'checked':''}> 画布整组移动 / 缩放 / 旋转</label>${l.groupId?'<button id="ungroup">解散当前组</button>':''}<details><summary>创建分组</summary><div class="group-list">${state.layers.map(x=>`<label><input type="checkbox" data-group-layer="${x.id}" ${x.id===selected?'checked':''}> ${esc(x.name)}</label>`).join('')}</div><button id="makeGroup">组合勾选图层</button></details></details>`;
 if($('cropToggle')){$('cropToggle').onclick=()=>{if(l.locked)return tell('请先解锁照片');cropMode=!cropMode;panMode=false;playing=false;time=0;dirty=true;renderEditingTools();tell(cropMode?'拖动框内照片；使用缩放滑杆调整，完成后再次点击按钮':'框内构图已完成')};let begun=false;$('cropZoom').oninput=()=>{if(l.locked)return;if(!begun){checkpoint();begun=true}l.fit='cover';l.crop={x:l.crop?.x??50,y:l.crop?.y??50,zoom:Number($('cropZoom').value)};dirty=true};$('cropZoom').onchange=()=>{begun=false;change()};$('cropReset').onclick=()=>{if(l.locked)return;checkpoint();l.crop={x:50,y:50,zoom:1};hydrate()}}
 $('groupMode').onchange=()=>{groupMode=$('groupMode').checked};if($('ungroup'))$('ungroup').onclick=()=>{checkpoint();const id=l.groupId;state.layers.filter(x=>x.groupId===id).forEach(x=>delete x.groupId);hydrate()};$('makeGroup').onclick=()=>{const ids=[...host.querySelectorAll('[data-group-layer]:checked')].map(x=>x.dataset.groupLayer);if(ids.length<2)return tell('至少勾选两个图层');checkpoint();const id=crypto.randomUUID();state.layers.filter(x=>ids.includes(x.id)).forEach(x=>x.groupId=id);hydrate();tell('已组合，拖动组内任意元素可整体变换')};
}
const viewBar=document.createElement('div');viewBar.className='view-tools';viewBar.innerHTML='<button id="viewFit">适应</button><button id="view100">100%</button><select id="viewZoom" aria-label="画布缩放"><option value="0">适应画布</option><option value="0.25">25%</option><option value="0.5">50%</option><option value="1">100%</option><option value="2">200%</option></select><button id="panToggle" aria-pressed="false">✥ 平移画布</button>';$('dropArea').append(viewBar);
function setView(z){viewZoom=z;panX=panY=0;$('viewZoom').value=String(z);dirty=true}
$('viewFit').onclick=()=>setView(0);$('view100').onclick=()=>setView(1);$('viewZoom').onchange=()=>setView(Number($('viewZoom').value));
cv.addEventListener('wheel',ev=>{if(exporting)return;ev.preventDefault();const wrap=$('canvasWrap'),r=wrap.getBoundingClientRect(),area=$('dropArea'),fit=Math.min((area.clientWidth-48)/cv.width,(area.clientHeight-65)/cv.height),old=cv.clientWidth/state.width||fit,next=Math.max(fit*.5,Math.min(4,old*Math.exp(-ev.deltaY*0.0012)));if(Math.abs(next-old)<1e-4)return;const k=next/old,dx=ev.clientX-(r.left+r.width/2),dy=ev.clientY-(r.top+r.height/2);panX=dx-k*(dx-panX);panY=dy-k*(dy-panY);viewZoom=next;const sel=$('viewZoom');let live=sel.querySelector('option[data-live]');if(!live){live=document.createElement('option');live.dataset.live='1';sel.append(live)}live.value=String(next);live.textContent=Math.round(next*100)+'%';sel.value=String(next);dirty=true},{passive:false});$('panToggle').onclick=()=>{panMode=!panMode;cropMode=false;$('panToggle').setAttribute('aria-pressed',panMode);cv.style.cursor=panMode?'grab':'default'};
cv.ondblclick=()=>{const l=state.layers.find(x=>x.id===selected);if(!l)return;if(l.type==='image'&&!l.locked){cropMode=true;panMode=false;setPanel('layers');renderProps();tell('已进入框内构图，拖动照片或调整照片缩放')}else startInlineEdit(l)};


const TEMPLATE_TITLES={eva:'终幕 / 大字宣言',post:'一条影像动态',memory:'Best memories 2008',phone:'未发送的短信',game:'存档点 1998',millennium:'千禧街角',album:'独立专辑 / SIDE A',collage:'剪贴日记'};
function templateFieldLabel(l,index){const name=(l.name||'').trim(),content=(l.content||'').trim();if(l.type==='image')return l.mask&&l.mask.type==='ellipse'?'头像照片':'照片';if(/^@/.test(name)||/^@/.test(content)||/账号|username|handle/i.test(name))return '账号 / @';if(/name|姓名|名字/i.test(name))return '姓名';if(/follow|关注/i.test(name))return '按钮文字';if(/时间|日期|date|year|\d{1,2}:\d{2}/i.test(name))return '时间 / 日期';if(/title|标题|宣言|post/i.test(name))return '标题';if(content.length>=14)return '正文';return '文字 '+(index+1)}
function renderTemplateFields(){const host=$('editingTools');if(!host||!state.layers.some(l=>l.type==='text'))return;const title=TEMPLATE_TITLES[state.template],texts=state.layers.filter(l=>l.type==='text'),images=state.layers.filter(l=>l.type==='image'),section=document.createElement('details');section.className='template-fields';section.open=!!title;section.innerHTML=`<summary>作品内容 / 快速填入</summary>${title?`<p class="template-current">当前模板：${esc(title)} <button type="button" data-clear-template>不再按模板显示</button></p><p>按模板字段填入，版式保持不变。</p>`:'<p>直接修改文字或替换照片；复杂排版仍可在图层中微调。</p>'}`+texts.map((l,i)=>`<label>${templateFieldLabel(l,i)}<textarea data-quick-text="${l.id}" ${l.locked?'disabled':''}>${esc(l.content)}</textarea></label>`).join('')+images.map(l=>`<div class="quick-image"><button data-quick-image="${l.id}" ${l.locked?'disabled':''}>替换：${templateFieldLabel(l,0)}</button><button data-quick-visible="${l.id}" ${l.locked?'disabled':''}>${l.hidden?'显示':'隐藏'}</button></div>`).join('');host.append(section);const clear=section.querySelector('[data-clear-template]');if(clear)clear.onclick=()=>{state.template=undefined;renderProps()};section.querySelectorAll('[data-quick-text]').forEach(input=>{let begun=false;input.oninput=()=>{const l=state.layers.find(x=>x.id===input.dataset.quickText);if(!begun){checkpoint();begun=true}l.content=input.value;fitTextHeight(l);dirty=true};input.onchange=()=>{begun=false;change()}});section.querySelectorAll('[data-quick-image]').forEach(b=>b.onclick=()=>{selected=b.dataset.quickImage;importMode='replace';$('imageFile').click()});section.querySelectorAll('[data-quick-visible]').forEach(b=>b.onclick=()=>{const l=state.layers.find(x=>x.id===b.dataset.quickVisible);checkpoint();l.hidden=!l.hidden;hydrate()});}
